[hidden] { display: none !important; }
:root { color-scheme: light; --ink: #222344; --muted: #777891; --paper: #fffdf7; --purple: #6654d9; --mint: #b8f2d0; --line: #e8e5dc; }
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 24px 16px; background-color: #f0efff; background-image: radial-gradient(#c9c5f1 1.5px, transparent 1.5px); background-size: 22px 22px; color: var(--ink); font: 16px/1.45 system-ui, sans-serif; }
.card { width: min(100%, 520px); padding: clamp(24px, 6vw, 42px); background: var(--paper); border: 3px solid var(--ink); box-shadow: 8px 8px 0 var(--ink); }
.header { text-align: center; }
.eyebrow, footer { color: var(--purple); font-size: 12px; font-weight: 800; letter-spacing: .13em; }
h1 { margin: 8px 0 2px; font-size: clamp(28px, 7vw, 36px); line-height: 1.15; letter-spacing: -.04em; }
.spark { display: inline-block; margin-left: 7px; color: var(--purple); font-size: .7em; vertical-align: top; }
.header p, .step-hint { margin: 8px 0 0; color: var(--muted); }
.progress-area { margin: 28px 0 30px; }
.progress-meta { display: flex; justify-content: space-between; color: var(--muted); font-size: 14px; font-weight: 700; }
.progress-track { height: 12px; margin-top: 9px; overflow: hidden; border: 2px solid var(--ink); background: #f0eef8; }
.progress-track span { display: block; width: 33.333%; height: 100%; background: var(--mint); transition: width .2s ease; }
.step-dots { display: flex; justify-content: space-between; margin: -7px 0 0; padding: 0 11%; list-style: none; }
.step-dots li { width: 14px; height: 14px; border: 2px solid var(--ink); background: var(--paper); }
.step-dots li.current { background: var(--purple); }
h2 { margin: 0; font-size: 22px; letter-spacing: -.02em; }
.step-hint { margin: 4px 0 20px; }
form label:not(.plan-card) { display: block; margin: 15px 0 6px; font-weight: 700; }
input[type="text"], input[type="email"] { width: 100%; min-height: 50px; padding: 11px 13px; border: 2px solid var(--ink); border-radius: 0; background: #fff; color: var(--ink); font: inherit; }
input::placeholder { color: #a1a0b2; }
input:focus-visible, button:focus-visible, .plan-card:focus-within { outline: 3px solid #8e82ff; outline-offset: 3px; }
.field-note { min-height: 22px; margin: 12px 0 0; color: var(--muted); font-size: 14px; }
.plans { display: grid; gap: 10px; margin: 0; padding: 0; border: 0; }
.plan-card { display: flex; align-items: center; gap: 12px; min-height: 72px; padding: 12px; border: 2px solid var(--line); cursor: pointer; transition: border-color .15s, transform .15s, background .15s; }
.plan-card:hover { border-color: var(--purple); transform: translateY(-1px); }
.plan-card:has(input:checked) { border-color: var(--purple); background: #f3f1ff; }
.plan-card input { width: 19px; height: 19px; margin: 0; accent-color: var(--purple); }
.plan-copy { display: grid; gap: 2px; flex: 1; }
.plan-copy strong { font-size: 16px; }
.plan-copy small { color: var(--muted); font-size: 14px; }
.badge { margin-left: 5px; padding: 3px 5px; background: var(--mint); font-size: 10px; letter-spacing: .06em; }
.plan-price { font-weight: 800; white-space: nowrap; }
.plan-price span { color: var(--muted); font-size: 13px; font-weight: 500; }
.summary { margin: 4px 0 18px; border: 2px solid var(--line); }
.summary div { display: flex; justify-content: space-between; gap: 16px; padding: 13px 14px; border-bottom: 1px solid var(--line); }
.summary div:last-child { border-bottom: 0; }
.summary dt { color: var(--muted); }
.summary dd { margin: 0; font-weight: 750; overflow-wrap: anywhere; text-align: right; }
.form-actions { display: flex; justify-content: space-between; gap: 12px; margin-top: 26px; }
.button { min-height: 50px; padding: 0 18px; border: 2px solid var(--ink); border-radius: 0; font: inherit; font-weight: 800; cursor: pointer; transition: transform .1s, box-shadow .1s, background .15s; }
.button:hover:not(:disabled) { transform: translate(-2px, -2px); box-shadow: 3px 3px 0 var(--ink); }
.button:active:not(:disabled) { transform: translate(1px, 1px); box-shadow: none; }
.button:disabled { color: #89899d; background: #e9e8ef; cursor: not-allowed; border-color: #aaa9b8; }
.primary { margin-left: auto; color: #fff; background: var(--purple); }
.secondary { color: var(--ink); background: var(--paper); }
.success-panel { padding: 10px 0 8px; text-align: center; }
.success-panel h2 { margin-top: 12px; }
.success-panel p { color: var(--muted); }
.success-icon { display: inline-grid; place-items: center; width: 52px; height: 52px; border: 2px solid var(--ink); background: var(--mint); font-size: 28px; font-weight: 900; }
footer { margin-top: 28px; text-align: center; font-size: 10px; }
footer span { margin-left: 5px; color: var(--ink); font-size: 15px; }
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (max-width: 390px) { body { padding: 16px 12px; } .card { padding: 23px 18px; box-shadow: 5px 5px 0 var(--ink); } .progress-area { margin: 23px 0 25px; } }

const form = document.querySelector('#signup-form');
const panels = [...document.querySelectorAll('.step-panel')];
const nextButton = document.querySelector('#next-button');
const backButton = document.querySelector('#back-button');
const confirmButton = document.querySelector('#confirm-button');
const progress = document.querySelector('[role="progressbar"]');
const progressFill = document.querySelector('#progress-fill');
const stepLabel = document.querySelector('#step-label');
const percentLabel = document.querySelector('#progress-percent');
const nameInput = document.querySelector('#name');
const emailInput = document.querySelector('#email');
let step = 1;

function validCurrentStep() {
  if (step === 1) return nameInput.value.trim().length >= 2 && emailInput.validity.valid && emailInput.value.trim() !== '';
  return Boolean(form.querySelector('input[name="plan"]:checked'));
}

function update() {
  panels.forEach((panel, index) => { panel.hidden = index + 1 !== step; });
  const percent = Math.round(step / 3 * 100);
  progress.setAttribute('aria-valuenow', String(step));
  progressFill.style.width = `${step / 3 * 100}%`;
  stepLabel.textContent = `Step ${step} of 3`;
  percentLabel.textContent = `${percent}%`;
  document.querySelectorAll('.step-dots li').forEach((dot, index) => dot.classList.toggle('current', index + 1 === step));
  nextButton.disabled = !validCurrentStep();
  backButton.hidden = step === 1;
  nextButton.hidden = step === 3;
  confirmButton.hidden = step !== 3;
  if (step === 3) {
    document.querySelector('#summary-name').textContent = nameInput.value.trim();
    document.querySelector('#summary-email').textContent = emailInput.value.trim();
    document.querySelector('#summary-plan').textContent = form.querySelector('input[name="plan"]:checked')?.value || '';
  }
}

[nameInput, emailInput].forEach(input => input.addEventListener('input', update));
form.querySelectorAll('input[name="plan"]').forEach(input => input.addEventListener('change', update));
nextButton.addEventListener('click', () => { if (validCurrentStep() && step < 3) { step += 1; update(); document.querySelector(`[data-step="${step}"] h2`).focus?.(); } });
backButton.addEventListener('click', () => { if (step > 1) { step -= 1; update(); } });
form.addEventListener('submit', event => {
  event.preventDefault();
  if (step !== 3 || !validCurrentStep()) return;
  panels.forEach(panel => { panel.hidden = true; });
  document.querySelector('#success-message').textContent = `Thanks, ${nameInput.value.trim()}! Your ${form.querySelector('input[name="plan"]:checked').value} plan is ready.`;
  document.querySelector('#success-panel').hidden = false;
  document.querySelector('#form-actions').hidden = true;
  progress.setAttribute('aria-valuenow', '3');
  progressFill.style.width = '100%';
  stepLabel.textContent = 'All done!';
  percentLabel.textContent = '100%';
});
update();
